-- ============================================================================
-- 0006_authoritative_articles.sql — 权威来源科普文章（10 篇成稿）
-- 来源：世界卫生组织（WHO）事实清单、国家卫生健康委公开文件、中国政府网
-- 说明：
--   1. 全部为编辑整理稿，非原文转载；每篇标注 source_info（硬性规则 7）
--   2. 只描述公开的流行病学数据与治疗原则，不做诊断、不给出个体化用药建议
--   3. 以 pending_review 入库，经后台审核后发布（审核流真实可追溯）
--   4. 幂等：ON DUPLICATE KEY UPDATE 只更新内容，不覆盖已有状态
--   5. 上线前仍需专业人员复核（docs/TODO.md T013）
-- ============================================================================

-- 1. 认识抑郁症 -------------------------------------------------------------
INSERT INTO articles (category_id, title, slug, summary, content, source_info, status)
SELECT c.id,
       '认识抑郁症：不只是"心情不好"',
       'depression-overview',
       '抑郁症是常见精神障碍，全球约 3.22 亿人患病。本文用世界卫生组织的数据说明它和普通情绪低落的区别，以及为什么它需要被认真对待。',
       '## 抑郁症是什么\n\n抑郁障碍（也称抑郁症）是一种常见的精神障碍。它不同于正常的情绪变化，而是涉及长时间的情绪低落，或失去快乐、对活动失去兴趣。世界卫生组织指出，抑郁症会影响生活的方方面面，包括与家人、朋友和社区的关系。\n\n## 它有多常见\n\n- 全球约有 3.22 亿人患有抑郁症（2023 年全球疾病负担数据）\n- 约 5.2% 的成年人患有抑郁症，其中男性 4.1%、女性 6.2%\n- 70 岁及以上人群中约为 5.4%\n- 女性患病率约为男性的 1.5 倍\n- 全球超过 10% 的孕妇和刚分娩的妇女患有抑郁症\n\n在中国，《健康中国行动（2019—2030年）》引用的数据显示，我国抑郁症患病率为 2.1%，焦虑障碍患病率为 4.98%。\n\n## 它不是"想开点就好"\n\n抑郁症是生物、心理和社会因素共同作用的结果。经历过虐待、重大损失或其他压力事件的人更容易患病，但这不意味着"意志薄弱"。抑郁症可能发生在任何人身上。\n\n## 需要提醒的是\n\n本文只提供科普信息，**不能用于自我诊断**。如果你怀疑自己或身边的人正被抑郁困扰，建议咨询精神科、心理科或心理咨询专业人员；如果出现伤害自己的念头，请立即使用本站的求助资源。\n\n> 本文不构成诊断或治疗建议。',
       '世界卫生组织《抑郁障碍（抑郁症）》事实清单（2026-09-11 更新）：https://www.who.int/zh/news-room/fact-sheets/detail/depression ；《健康中国行动（2019—2030年）》心理健康促进行动',
       'pending_review'
FROM article_categories c WHERE c.slug = 'understanding'
ON DUPLICATE KEY UPDATE title = VALUES(title), summary = VALUES(summary), content = VALUES(content), source_info = VALUES(source_info), category_id = VALUES(category_id);

-- 2. 抑郁发作的常见信号 ------------------------------------------------------
INSERT INTO articles (category_id, title, slug, summary, content, source_info, status)
SELECT c.id,
       '抑郁发作的常见信号：为什么强调"两周"',
       'depression-signals',
       '情绪低落很常见，但持续时间、强度和影响范围是关键。本文列出世界卫生组织描述的抑郁发作表现，帮你判断什么时候该寻求专业帮助。',
       '## 核心表现\n\n在抑郁发作期间，一个人会经历抑郁情绪（感到悲伤、烦躁、空虚），或对活动失去乐趣和兴趣。\n\n## 抑郁发作不同于正常的情绪波动\n\n世界卫生组织的描述是：抑郁情绪几乎每天出现，在一天中的大部分时间持续，**至少持续两周**。\n\n## 可能同时出现的其他表现\n\n- 注意力不集中\n- 过度内疚或自我价值感低下\n- 对未来感到绝望\n- 有死亡或自杀的想法\n- 睡眠紊乱\n- 食欲或体重变化\n- 感觉非常疲倦或精力不足\n\n## 轻度、中度与重度\n\n抑郁发作按症状数量、严重程度和对日常生活功能的影响，分为轻度、中度或重度。类型上还可分为单次发作、复发性抑郁障碍，以及与躁狂症状交替出现的双相情感障碍——**双相情感障碍的治疗方案不同**，因此专业评估很重要。\n\n## 你可以做什么\n\n1. 记录情绪和睡眠的变化，留意持续了多久\n2. 如果上述表现持续两周以上并影响工作、学习或人际，建议预约精神科或心理科\n3. 如果出现伤害自己的念头，不要独自承受，立即联系信任的人或拨打心理援助热线\n\n**本文不能诊断你**。以上内容仅用于帮助你识别何时该寻求专业帮助。',
       '世界卫生组织《抑郁障碍（抑郁症）》事实清单（2026-09-11 更新），症状和类型部分：https://www.who.int/zh/news-room/fact-sheets/detail/depression',
       'pending_review'
FROM article_categories c WHERE c.slug = 'understanding'
ON DUPLICATE KEY UPDATE title = VALUES(title), summary = VALUES(summary), content = VALUES(content), source_info = VALUES(source_info), category_id = VALUES(category_id);

-- 3. 成因 --------------------------------------------------------------------
INSERT INTO articles (category_id, title, slug, summary, content, source_info, status)
SELECT c.id,
       '抑郁症是怎么发生的：生物、心理与社会因素',
       'depression-causes',
       '抑郁症不是单一原因造成的。生理、成长经历与现实压力相互作用。理解这一点，有助于减少自责，也更容易找到合适的帮助方式。',
       '## 不是单一原因\n\n世界卫生组织指出，抑郁症是社会、心理和生物因素综合作用的结果。\n\n## 常见的影响因素\n\n- 不良生活事件：失业、丧亲、创伤性事件等\n- 长期压力：工作、学业、照护负担、人际关系冲突\n- 身体健康状况：缺乏身体活动、有害使用酒精等既是抑郁症的相关因素，也是心血管疾病、糖尿病和呼吸系统疾病的已知危险因素\n- 患病后的恶性循环：抑郁会带来更大的压力和功能受损，反过来加重症状\n\n## 关于遗传\n\n家族史会增加风险，但并不是命运。具体风险的评估需要专业遗传咨询，本文不展开概率数字。\n\n## 预防：哪些做法被证明有帮助\n\n世界卫生组织提到，预防规划可以减少抑郁症，例如：\n\n- 在学校开展增强儿童和青少年积极应对方式的规划\n- 对有行为问题儿童的父母进行干预\n- 为老年人开展体育运动规划\n\n## 写给你\n\n如果你正在经历抑郁，请不必把原因归结为"我不够坚强"。理解成因的意义在于：它提示了可以介入的环节——就医、调整生活节律、争取社会支持。\n\n> 本文为科普信息，不构成诊断或治疗建议。',
       '世界卫生组织《抑郁障碍（抑郁症）》事实清单（2026-09-11 更新），成因和预防部分：https://www.who.int/zh/news-room/fact-sheets/detail/depression',
       'pending_review'
FROM article_categories c WHERE c.slug = 'understanding'
ON DUPLICATE KEY UPDATE title = VALUES(title), summary = VALUES(summary), content = VALUES(content), source_info = VALUES(source_info), category_id = VALUES(category_id);

-- 4. 治疗 --------------------------------------------------------------------
INSERT INTO articles (category_id, title, slug, summary, content, source_info, status)
SELECT c.id,
       '抑郁症怎么治：心理治疗、药物与分级方案',
       'depression-treatment',
       '抑郁症已有行之有效的治疗方法。轻度以心理治疗为主，中重度可能需要联合治疗。本文梳理世界卫生组织给出的治疗原则，帮你在就诊前建立基本认知。',
       '## 有效治疗是存在的\n\n世界卫生组织明确指出：抑郁症已有有效治疗方法，包括心理治疗和药物。如果你有抑郁症的症状，请就医。\n\n## 心理治疗是首选\n\n- 心理治疗是抑郁症的首选治疗方法\n- 轻度抑郁症不需要抗抑郁药物\n- 中度和重度抑郁症，心理治疗可以与抗抑郁药物联合使用\n\n常见的有效心理治疗包括：行为激活、认知行为疗法、人际心理治疗、解决问题疗法。心理治疗可以面对面进行，也可以在线进行，还可以通过自助手册、网站和应用程序获得。\n\n## 关于药物\n\n抗抑郁药物包括选择性 5-羟色胺再摄取抑制剂（SSRI）等类别。世界卫生组织同时提醒：\n\n- 卫生保健提供者需要权衡可能的副作用、干预能力与个人偏好\n- 抗抑郁药物不应用于治疗儿童抑郁症，也不应是青少年的一线治疗手段，对青少年应慎用\n- 双相情感障碍有不同的药物和治疗方法\n\n**具体用不用药、用什么药、用多久，必须由精神科医生评估后决定**，请不要自行购买、加量或停药。\n\n## 治疗路上常见的障碍\n\n世界卫生组织指出，有效治疗的障碍包括精神卫生投入不足、训练有素的卫生服务提供者不足，以及社会对精神疾患的歧视。在高收入国家，也只有大约三分之一的抑郁症患者接受过精神卫生治疗。\n\n这意味着：没有得到治疗，往往不是你的错，而是可及性与病耻感的问题。主动求助本身就是有效的一步。\n\n> 本文为科普信息，不构成诊断或治疗建议；用药相关问题请咨询精神科医生或药师。',
       '世界卫生组织《抑郁障碍（抑郁症）》事实清单（2026-09-11 更新），诊断和治疗部分：https://www.who.int/zh/news-room/fact-sheets/detail/depression',
       'pending_review'
FROM article_categories c WHERE c.slug = 'getting-help'
ON DUPLICATE KEY UPDATE title = VALUES(title), summary = VALUES(summary), content = VALUES(content), source_info = VALUES(source_info), category_id = VALUES(category_id);

-- 5. 日常自我照顾 ------------------------------------------------------------
INSERT INTO articles (category_id, title, slug, summary, content, source_info, status)
SELECT c.id,
       '日常自我照顾：世界卫生组织建议的几件小事',
       'self-care-daily',
       '在专业治疗之外，自我照顾能帮助管理症状、维持整体健康。这些建议不替代治疗，但可以从今天开始，一件一件做。',
       '## 自我照顾能做什么\n\n世界卫生组织指出，自我照顾可以在管理抑郁症症状和促进整体健康方面发挥重要作用。\n\n## 可以尝试的事\n\n- 尝试继续从事你曾经喜欢的活动\n- 与朋友和家人保持联系\n- 定期锻炼，即使只是散散步\n- 尽可能坚持规律的饮食和睡眠习惯\n- 避免或减少饮酒，不要使用非法药物——它们可能使抑郁症恶化\n- 与你信任的人谈谈你的感受\n- 向卫生保健提供者寻求帮助\n\n## 关于"做不到"\n\n抑郁会让人失去动力，做不到上面这些并不代表你不够努力。可以从最小的一步开始：今天出门走十分钟，或者给一个信任的人发条消息。完成比完美重要。\n\n## 如果你有自杀念头\n\n世界卫生组织的建议是：\n\n- 请记住，你并不孤单，许多人都经历过你正在经历的事情并找到了帮助\n- 与你信任的人谈谈你的感受\n- 与卫生工作者交谈，例如医生或咨询师\n- 加入支持小组\n- 如果你认为存在伤害自己的直接危险，请联系任何可用的紧急服务或危机热线\n\n本站求助页汇总了可用的求助渠道。\n\n> 本文为科普信息，不构成诊断或治疗建议；自我照顾不能替代专业治疗。',
       '世界卫生组织《抑郁障碍（抑郁症）》事实清单（2026-09-11 更新），自我保健部分：https://www.who.int/zh/news-room/fact-sheets/detail/depression',
       'pending_review'
FROM article_categories c WHERE c.slug = 'self-care'
ON DUPLICATE KEY UPDATE title = VALUES(title), summary = VALUES(summary), content = VALUES(content), source_info = VALUES(source_info), category_id = VALUES(category_id);

-- 6. 自杀念头（危机主题，措辞严格遵循硬性规则 1）-----------------------------
INSERT INTO articles (category_id, title, slug, summary, content, source_info, status)
SELECT c.id,
       '当出现"活着没意思"的念头：立刻可以做的事',
       'suicidal-thoughts',
       '自杀念头是痛苦的信号，不是软弱，也不是不可改变。本文依据世界卫生组织的建议，说明当下可以采取的求助动作，以及身边人可以怎么陪伴。',
       '> 如果你现在有伤害自己的打算或已经做了准备，请立即拨打 120 或前往最近的急诊；也可以拨打全国统一心理援助热线 12356。\n\n## 先说一件事\n\n自杀是可以预防的。世界卫生组织的数据显示，2021 年全球估计有 72.7 万人因自杀死亡，自杀是 15—29 岁人群的第三大死因。这些数字背后，是大量在痛苦中没能及时获得帮助的人。\n\n## 当下可以做的四件事\n\n1. **告诉一个人**：与信任的家人、朋友或同事谈谈你的感受，不需要说得很有条理\n2. **联系专业人员**：与卫生工作者交谈，例如医生或咨询师；或拨打心理援助热线\n3. **远离危险**：暂时把可能伤害自己的物品交给他人保管，尽量不独处\n4. **去急诊**：如果你认为存在伤害自己的直接危险，请联系紧急服务或直接前往医院急诊\n\n## 如果你是身边的人\n\n- 认真对待，不要用"想开点""别矫情"回应\n- 直接问一句"你最近是不是有伤害自己的念头"，然后安静地听\n- 陪他/她一起联系专业机构或前往就诊，而不是让其独自处理\n- 在危机过去后继续保持联系\n\n## 关于本站\n\n本站的危机干预机制会在量表作答、日记、社区发帖和 AI 对话中识别风险信号，并展示求助资源、生成后台预警工单。**但本站不能替代急救**。如果你处于紧急危险中，请优先联系急救服务。',
       '世界卫生组织《抑郁障碍（抑郁症）》事实清单（2026-09-11 更新）；国家卫生健康委《关于应用"12356"全国统一心理援助热线电话号码的通知》（国卫医政函〔2024〕259号）',
       'pending_review'
FROM article_categories c WHERE c.slug = 'getting-help'
ON DUPLICATE KEY UPDATE title = VALUES(title), summary = VALUES(summary), content = VALUES(content), source_info = VALUES(source_info), category_id = VALUES(category_id);

-- 7. 求助路径 ----------------------------------------------------------------
INSERT INTO articles (category_id, title, slug, summary, content, source_info, status)
SELECT c.id,
       '在中国如何求助：从心理热线到精神专科',
       'where-to-get-help',
       '不知道去哪看、挂什么科、要不要吃药，是很多人卡住的地方。本文依据国家卫生健康委的公开文件，梳理从热线、综合医院到精神专科医院的就诊路径。',
       '## 第一步：可以先打电话\n\n国家卫生健康委在 2024 年 12 月印发通知，协调工业和信息化部设置 **12356** 作为全国统一心理援助热线电话号码，要求各地在 2025 年 5 月 1 日 0 时前实现拨打 12356 接通心理援助热线。\n\n按要求，原则上每个设区的市至少开通 1 条心理援助热线，每条热线至少设置 2 个坐席，每日提供不少于 18 小时服务。热线提供心理健康教育、心理咨询、心理疏导、心理危机干预等服务。\n\n## 第二步：选择合适的机构\n\n- **综合医院精神科 / 心理科**：适合首次就诊、需要评估与用药指导\n- **精神专科医院**：适合症状复杂、需要系统治疗或存在自伤风险的情况\n- **妇幼保健院**：孕产期情绪问题可就近咨询（国家要求妇幼保健院开设精神（心理）科）\n- **社区卫生服务中心 / 乡镇卫生院**：可做初步筛查与转介\n\n2025 年卫生健康系统为民服务实事项目提出，每个地级市至少有 1 所医院提供心理门诊、睡眠门诊服务。\n\n## 第三步：就诊前准备什么\n\n- 症状从什么时候开始、持续多久、有没有诱因\n- 睡眠、食欲、体重、精力的变化\n- 工作、学习、人际受影响的程度\n- 既往就诊与用药情况、家族史\n- 是否有过伤害自己的念头（请如实告诉医生）\n\n## 关于筛查\n\n国家卫生健康委 2020 年印发的《探索抑郁症防治特色服务工作方案》提出，医疗卫生机构使用 PHQ-9 量表开展抑郁症筛查；体检中心在体检项目中纳入情绪状态评估；高中及高等院校将抑郁症筛查纳入学生健康体检内容。\n\n**筛查结果不等于诊断**。量表提示风险时，需要由专业人员进一步评估。',
       '国家卫生健康委《关于应用"12356"全国统一心理援助热线电话号码的通知》（2024-12）；《探索抑郁症防治特色服务工作方案》（2020-09）；《关于实施2025年卫生健康系统为民服务实事项目的通知》（2025-02）',
       'pending_review'
FROM article_categories c WHERE c.slug = 'getting-help'
ON DUPLICATE KEY UPDATE title = VALUES(title), summary = VALUES(summary), content = VALUES(content), source_info = VALUES(source_info), category_id = VALUES(category_id);

-- 8. 重点人群 ----------------------------------------------------------------
INSERT INTO articles (category_id, title, slug, summary, content, source_info, status)
SELECT c.id,
       '四类重点人群：青少年、孕产妇、老年人与高压职业者',
       'key-groups',
       '不同人生阶段的抑郁风险与求助方式并不相同。本文依据国家卫生健康委的方案，梳理四类重点人群的服务措施，方便你对号入座地找到资源。',
       '## 为什么划分重点人群\n\n国家卫生健康委《探索抑郁症防治特色服务工作方案》针对青少年、孕产妇、老年人、高压职业人群分别提出了心理健康服务措施，原因是这些阶段的压力源、就诊障碍和可及资源差异很大。\n\n## 青少年\n\n- 中学、高等院校设置心理辅导（咨询）室和心理健康教育课程，配备心理健康教育教师\n- 心理健康教育作为必修课，指导学生科学认识抑郁症、及时寻求专业帮助\n- 抑郁症筛查纳入学生健康体检内容，建立学生心理健康档案，对测评结果异常的学生给予重点关注\n\n## 孕产妇\n\n- 抑郁症防治知识作为孕妇学校必备的科普宣教内容\n- 孕产期抑郁症筛查纳入常规孕检和产后访视流程\n- 鼓励精神专科医院、综合医院精神科与妇产科、妇幼保健院以联合门诊或远程会诊形式提供支持\n- 世界卫生组织的数据显示，全球超过 10% 的孕妇和刚分娩的妇女患有抑郁症\n\n## 老年人\n\n- 基层医疗卫生机构结合家庭医生签约服务、老年人健康体检，每年为辖区老年人开展精神健康筛查\n- 对经心理测评有抑郁情绪的老人提供心理咨询和及时转诊\n- 70 岁及以上人群抑郁症患病率约为 5.4%（世界卫生组织数据）\n\n## 高压职业人群\n\n- 机关、企事业和其他用人单位将职工心理健康作为单位文化建设的重要内容\n- 创造有益于身心健康的工作环境，聘用专兼职的精神心理专业人员\n\n## 如果你是其中一员\n\n重点人群身份不是标签，而是提示：你所在的环境里，通常已经有可以使用的资源——学校心理老师、孕妇学校、家庭医生、单位 EAP。先把这些资源用起来，必要时再到专科就诊。',
       '国家卫生健康委《探索抑郁症防治特色服务工作方案》（2020-09）；世界卫生组织《抑郁障碍（抑郁症）》事实清单（2026-09-11 更新）',
       'pending_review'
FROM article_categories c WHERE c.slug = 'understanding'
ON DUPLICATE KEY UPDATE title = VALUES(title), summary = VALUES(summary), content = VALUES(content), source_info = VALUES(source_info), category_id = VALUES(category_id);

-- 9. 睡眠与情绪 --------------------------------------------------------------
INSERT INTO articles (category_id, title, slug, summary, content, source_info, status)
SELECT c.id,
       '睡眠与情绪：为什么规律作息是基础',
       'sleep-and-mood',
       '睡眠紊乱既是抑郁的常见表现，也会反过来加重情绪问题。本文结合《健康中国行动》的建议，说明睡眠与情绪的关系，以及什么时候该看睡眠门诊。',
       '## 睡眠紊乱是抑郁的常见表现\n\n世界卫生组织在抑郁发作的表现中明确列出"睡眠紊乱"。它可能是入睡困难、早醒，也可能是睡得过多。\n\n## 成人每天睡多久\n\n《健康中国行动（2019—2030年）》提倡，成人每日平均睡眠时间为 7—8 小时，并提出"重视睡眠健康"：工作、学习、娱乐、休息都要按作息规律进行，注意起居有常。\n\n## 可以尝试的做法\n\n- 固定起床时间，比固定入睡时间更容易坚持\n- 睡前一小时减少强光与手机刺激\n- 白天有适量活动，避免长时间卧床\n- 减少用酒精助眠——酒精会破坏后半夜的睡眠结构\n\n这些是生活层面的建议，不能替代治疗。如果长期失眠并伴随情绪低落、兴趣减退，建议就诊。\n\n## 什么时候该看睡眠门诊\n\n2025 年卫生健康系统为民服务实事项目提出，每个地级市至少有 1 所医院提供心理门诊、睡眠门诊服务。出现以下情况时可以考虑就诊：\n\n- 失眠持续数周以上，影响白天功能\n- 早醒并伴有情绪低落、兴趣减退\n- 打鼾严重、白天嗜睡（可能涉及睡眠呼吸问题）\n- 自行调整作息两周仍无改善\n\n## 提醒\n\n不要自行长期使用助眠药物。用药与停药方案应由医生评估。',
       '《健康中国行动（2019—2030年）》心理健康促进行动；《关于实施2025年卫生健康系统为民服务实事项目的通知》（2025-02）；世界卫生组织《抑郁障碍（抑郁症）》事实清单',
       'pending_review'
FROM article_categories c WHERE c.slug = 'self-care'
ON DUPLICATE KEY UPDATE title = VALUES(title), summary = VALUES(summary), content = VALUES(content), source_info = VALUES(source_info), category_id = VALUES(category_id);

-- 10. 常见误解 ---------------------------------------------------------------
INSERT INTO articles (category_id, title, slug, summary, content, source_info, status)
SELECT c.id,
       '关于抑郁症的五个常见误解',
       'myths-and-stigma',
       '"矫情""想开点就好""看心理科就是精神病"——这些说法让很多人错过了帮助。本文用权威资料逐条回应，也给出更合适的表达方式。',
       '## 误解一：抑郁症就是矫情、抗压能力差\n\n世界卫生组织的表述是：抑郁症是生物、心理和社会因素综合作用的结果，可能发生在任何人身上。经历过虐待、重大损失或其他压力事件的人更容易患病。把它归因为性格缺陷，既不准确，也会阻碍求助。\n\n## 误解二：靠意志力就能好\n\n抑郁症已有有效治疗方法，包括心理治疗和药物。轻度抑郁症以心理治疗为主，中重度可能需要联合治疗。意志力可以帮助你走进诊室，但不能替代治疗。\n\n## 误解三：吃药会"上瘾"，能不吃就不吃\n\n抗抑郁药物的使用需要医生评估，包括种类、剂量和疗程。**不要自行购买、加量或停药**；如果担心副作用或依赖问题，请直接向精神科医生或药师提出，由专业人员判断。世界卫生组织也提醒，对儿童和青少年使用抗抑郁药物需特别谨慎。\n\n## 误解四：看心理科就等于"精神病"\n\n心理健康是健康的重要组成部分。《健康中国行动（2019—2030年）》把心理健康促进行动列为专项行动之一，并提出到 2022 年和 2030 年居民心理健康素养水平提升到 20% 和 30%。心理门诊、睡眠门诊正在成为综合医院的常规配置。\n\n## 误解五：说了"抑郁"就是给他贴标签\n\n国家卫生健康委在相关文件中提到，公众对常见精神障碍的认知率仍比较低，部分患者及家属存在病耻感。语言确实有力量：\n\n- 不说"你就是抑郁症"，说"你最近的状态值得找专业的人看看"\n- 不说"别想太多"，说"我在，你想说的时候我听"\n- 不替对方做诊断，也不替对方停药\n\n## 写在最后\n\n本站所有内容只做科普，不提供诊断。如果你或身边的人正在受到影响，建议咨询专业人员；如有伤害自己的念头，请立即使用求助资源。',
       '世界卫生组织《抑郁障碍（抑郁症）》事实清单（2026-09-11 更新）；《健康中国行动（2019—2030年）》心理健康促进行动；国家卫生健康委《探索抑郁症防治特色服务工作方案》（2020-09）',
       'pending_review'
FROM article_categories c WHERE c.slug = 'understanding'
ON DUPLICATE KEY UPDATE title = VALUES(title), summary = VALUES(summary), content = VALUES(content), source_info = VALUES(source_info), category_id = VALUES(category_id);
